ALTER TABLE "imports" ADD "additional_data_extraction_status" integer DEFAULT 0 NOT NULL;
ALTER TABLE "imports" ADD "additional_data_extraction" jsonb DEFAULT '{}' NOT NULL;
CREATE INDEX "index_imports_on_additional_data_extraction_status" ON "imports" ("additional_data_extraction_status");
UPDATE pg_index SET indisvalid = false WHERE indexrelid = 'index_imports_on_additional_data_extraction_status'::regclass;
ALTER TABLE "visits" ADD "import_id" bigint;
CREATE INDEX "idx_visits_import_id_extracted" ON "visits" ("import_id") WHERE import_id IS NOT NULL;
ALTER TABLE "places" ADD "import_id" bigint;
CREATE INDEX "idx_places_import_id_extracted" ON "places" ("import_id") WHERE import_id IS NOT NULL;
ALTER TABLE "tracks" ADD "import_id" bigint;
CREATE INDEX "idx_tracks_import_id_extracted" ON "tracks" ("import_id") WHERE import_id IS NOT NULL;
CREATE UNIQUE INDEX "idx_visits_user_started_at_place_unique" ON "visits" ("user_id", "started_at", "place_id");
UPDATE pg_index SET indisvalid = false WHERE indexrelid = 'idx_visits_user_started_at_place_unique'::regclass;
CREATE UNIQUE INDEX "idx_track_segments_track_start_index_unique" ON "track_segments" ("track_id", "start_index");
UPDATE pg_index SET indisvalid = false WHERE indexrelid = 'idx_track_segments_track_start_index_unique'::regclass;
CREATE UNIQUE INDEX idx_places_user_external_place_id ON places (user_id, ((geodata ->> 'external_place_id'))) WHERE (geodata ->> 'external_place_id') IS NOT NULL;
UPDATE pg_index SET indisvalid = false WHERE indexrelid = 'idx_places_user_external_place_id'::regclass;
